def slug(s): return re.sub(r'[^a-z0-9]+','-',s.lower()).strip('-')
cs=[]
for (row,icon) in zip(rows,icons):
    name,cat,A,C,P,H,skills,why,experiment,related=row
    sl=slug(name); skill=[x.strip() for x in skills.split(',')]
    cs.append({"id":sl,"name":name,"category":cat,"icon":icon,"tagline":why+".","reason":why,"scores":{"analytical":A,"creative":C,"people":P,"handsOn":H},"weights":{"analytical":A/100,"creative":C/100,"people":P/100,"handsOn":H/100},"skills":skill,"why":why,"experiment":experiment,"related":[x.strip() for x in related.split(';')],"paths":paths[name],"description":f"{name} is a career path where you apply {', '.join(skill[:3]).lower()} to real problems and projects. The route is best understood by trying a small piece of the work, not by reading a job title alone.","responsibilities":[f"Use {skill[0].lower()} to work on real problems",f"Apply {skill[1].lower()} in practical situations","Communicate your work, decisions or findings","Iterate, learn and improve based on evidence and feedback"],"challenges":["The day-to-day work can be different from how the career is portrayed online","The field requires continued learning and adaptation","A small experiment only represents one slice of the profession"],"activity":{"intro":f"Get a small taste of this career: {experiment.lower()}.","title":experiment,"instructions":"You don't need professional-level knowledge. Focus on the way you approach the problem and how the work feels.","challenge":experiment,"steps":[f"Spend a few minutes understanding the problem behind: {experiment}.","Create a small first attempt using what you already know.","Notice what part of the task felt energizing or frustrating.","Write down one thing you would want to learn next.","Ask yourself: would I voluntarily try another task like this?"]}})
(data/'careers.js').write_text('const careers = '+json.dumps(cs,indent=2,ensure_ascii=False)+'''\n\ncareers.forEach(career => {\n  career.personalized = (scores) => {\n    const strongest = Object.entries(scores).sort((a,b) => b[1] - a[1]).slice(0, 2);\n    const labels = { analytical: "analytical", creative: "creative", people: "people-focused", handsOn: "hands-on" };\n    return `${career.why}. Your strongest current profile signals are ${labels[strongest[0][0]]} and ${labels[strongest[1][0]]}. This is a starting clue, not a verdict — the best way to learn whether the route fits is to try a small piece of the work.`;\n  };\n});\n\nexport default careers;\n''')

app=root/'src/App.jsx'; t=app.read_text()
t=t.replace('const [selected, setSelected] = useState(answers[questions[0].id] || null);','const [selected, setSelected] = useState(answers[questions[0].id]?.option || null);\n  const [startedAt, setStartedAt] = useState(Date.now());\n  const [secondsLeft, setSecondsLeft] = useState(5);')
t=t.replace('''  const progress = ((current + 1) / questions.length) * 100;\n\n  function choose(option) {\n    setSelected(option.id);\n    setAnswers(prev => ({ ...prev, [q.id]: option.id }));\n  }''','''  const progress = ((current + 1) / questions.length) * 100;\n\n  React.useEffect(() => {\n    setStartedAt(Date.now());\n    setSecondsLeft(5);\n  }, [current]);\n\n  React.useEffect(() => {\n    const timer = setInterval(() => setSecondsLeft(prev => prev > 0 ? prev - 1 : 0), 1000);\n    return () => clearInterval(timer);\n  }, [current]);\n\n  function choose(option) {\n    const elapsed = (Date.now() - startedAt) / 1000;\n    setSelected(option.id);\n    setAnswers(prev => ({ ...prev, [q.id]: { option: option.id, fast: elapsed < 1.5 } }));\n  }''')
t=t.replace('setSelected(answers[nextQ.id] || null);','setSelected(answers[nextQ.id]?.option || null);')
t=t.replace('<div className="question-meta"><Clock3 size={16}/> Go with your first instinct</div>','<div className="question-meta"><span><Clock3 size={16}/> Go with your first instinct</span><span className={secondsLeft <= 1 ? "timer urgent" : "timer"}>{secondsLeft}s</span></div>')
old='''function calculateScores(answers) {\n  const raw = { analytical: 0, creative: 0, people: 0, handsOn: 0 };\n  questions.forEach(q => {\n    const answer = q.options.find(o => o.id === answers[q.id]);\n    if (answer) raw[answer.axis] += answer.weight || 1;\n  });\n  const max = Math.max(...Object.values(raw), 1);\n  const scores = {};\n  Object.keys(raw).forEach(k => scores[k] = Math.round((raw[k] / max) * 100));\n  return scores;\n}\n\nfunction getMatches(scores) {\n  return [...careers]\n    .map(c => {\n      const fit = c.weights.analytical * scores.analytical +\n        c.weights.creative * scores.creative +\n        c.weights.people * scores.people +\n        c.weights.handsOn * scores.handsOn;\n      return {...c, fit};\n    })\n    .sort((a,b) => b.fit - a.fit)\n    .slice(0,3);\n}'''
new='''function calculateScores(answers) {\n  const raw = { analytical: 0, creative: 0, people: 0, handsOn: 0 };\n  questions.forEach(q => {\n    const response = answers[q.id];\n    if (!response) return;\n    const answer = q.options.find(o => o.id === response.option);\n    if (answer) raw[answer.axis] += response.fast ? 1.25 : 1;\n  });\n  const maxPerAxis = 5 * 1.25;\n  return Object.fromEntries(Object.entries(raw).map(([axis, value]) => [axis, Math.round((value / maxPerAxis) * 100)]));\n}\n\nfunction getMatches(scores) {\n  const user = [scores.analytical, scores.creative, scores.people, scores.handsOn];\n  return [...careers].map(c => {\n    const target = [c.scores.analytical, c.scores.creative, c.scores.people, c.scores.handsOn];\n    const distance = Math.sqrt(target.reduce((sum, value, i) => sum + Math.pow(value - user[i], 2), 0));\n    const fit = Math.max(0, Math.round(100 - (distance / 200) * 100));\n    return {...c, fit};\n  }).sort((a,b) => b.fit - a.fit).slice(0,3);\n}'''
if old not in t: raise SystemExit('scoring block not found')
t=t.replace(old,new)
app.write_text(t)
